using System.Globalization;

namespace ResonantPulse.App.Localization;

/// <summary>Every application-authored visible/automation string lives here.
/// User names and OS/provider diagnostics are deliberately not translated.</summary>
public static class Text
{
    private static readonly Dictionary<string, string[]> Strings = new(StringComparer.Ordinal);
    internal static string InitialSystemLanguage { get; } = CultureInfo.CurrentUICulture.TwoLetterISOLanguageName;
    private static int _language;
    public static string Language { get; private set; } = "";
    public static CultureInfo Culture { get; private set; } = CultureInfo.CurrentCulture;

    public static void Select(string language)
    {
        Language = language;
        var code = string.IsNullOrWhiteSpace(language)
            ? InitialSystemLanguage : language;
        _language = code switch { "nl" => 1, "de" => 2, "fr" => 3, "es" => 4, _ => 0 };
        Culture = CultureInfo.GetCultureInfo(code is "nl" or "de" or "fr" or "es" ? code : "en");
        CultureInfo.CurrentCulture = Culture;
        CultureInfo.CurrentUICulture = Culture;
    }

    public static string Get(string key) =>
        Strings.TryGetValue(key, out var values) ? values[_language] : key;
    internal static IEnumerable<string> Keys => Strings.Keys;
    public static string Format(string key, params object[] values) => string.Format(Culture, Get(key), values);
    public static bool TryLocalizeKnownMessage(string message, out string translated)
    {
        foreach (var variants in Strings.Values)
        {
            if (!variants.Contains(message, StringComparer.Ordinal)) continue;
            translated = variants[_language];
            return true;
        }
        translated = "";
        return false;
    }

    private static void Add(string key, string en, string nl, string de, string fr, string es) =>
        Strings.Add(key, [en, nl, de, fr, es]);

