        Add("ProgramEmpty", "This project has no program, so the rhythm simply repeats. Build a program in Studio, or start from a ready-made one in the Library.", "Dit project heeft geen programma, dus het ritme blijft zich herhalen. Bouw een programma in Studio of begin met een kant-en-klaar programma in de Bibliotheek.", "Dieses Projekt hat kein Programm, der Rhythmus wiederholt sich also einfach. Bauen Sie im Studio ein Programm oder beginnen Sie mit einem fertigen aus der Bibliothek.", "Ce projet n’a pas de programme : le rythme se répète simplement. Créez un programme dans Studio ou partez d’un programme prêt à l’emploi dans la Bibliothèque.", "Este proyecto no tiene programa, así que el ritmo simplemente se repite. Cree un programa en Estudio o empiece con uno listo para usar en la Biblioteca.");
        Add("Progress", "Played {0} of {1}", "Gespeeld: {0} van {1}", "Gespielt: {0} von {1}", "Joué : {0} sur {1}", "Reproducido: {0} de {1}");
        Add("TimingLab", "Timing check", "Timingcheck", "Timing-Prüfung", "Contrôle rythmique", "Comprobación de tiempo");
        Add("TimingLimits", "Press F (or Hit) in time with the clicks and see how close you land. It compares when each press arrives with when each click was scheduled. It cannot hear your instrument and does not measure the delay of your speakers or keyboard.", "Druk op F (of Aanslag) in de maat met de tikken en zie hoe dicht u erbij komt. Het vergelijkt wanneer elke toetsdruk aankomt met wanneer elke tik was gepland. Het hoort uw instrument niet en meet de vertraging van uw luidsprekers of toetsenbord niet.", "Drücken Sie F (oder Anschlag) im Takt der Klicks und sehen Sie, wie genau Sie treffen. Verglichen wird, wann jeder Tastendruck ankommt und wann jeder Klick geplant war. Ihr Instrument wird nicht gehört, und die Verzögerung Ihrer Lautsprecher oder Tastatur wird nicht gemessen.", "Appuyez sur F (ou Frappe) en rythme avec les clics et voyez à quel point vous êtes précis. Le contrôle compare l’instant d’arrivée de chaque pression à l’instant prévu de chaque clic. Il n’entend pas votre instrument et ne mesure pas le retard de vos haut-parleurs ou de votre clavier.", "Pulse F (o Golpe) al ritmo de los clics y vea cuánto se acerca. Compara el momento en que llega cada pulsación con el momento previsto de cada clic. No oye su instrumento ni mide el retraso de sus altavoces o teclado.");
        Add("BeginTiming", "Start check", "Check starten", "Prüfung starten", "Démarrer le contrôle", "Iniciar comprobación");
        Add("Hit", "Hit (F)", "Aanslag (F)", "Anschlag (F)", "Frappe (F)", "Golpe (F)");
        Add("FinishTiming", "Finish and show result", "Afronden en resultaat tonen", "Beenden und Ergebnis anzeigen", "Terminer et afficher le résultat", "Terminar y mostrar resultado");
        Add("TimingArmed", "Check running · press F in time with the clicks", "Check loopt · druk op F in de maat met de tikken", "Prüfung läuft · drücken Sie F im Takt der Klicks", "Contrôle en cours · appuyez sur F en rythme avec les clics", "Comprobación en curso · pulse F al ritmo de los clics");
        Add("TimingReport", "Hit {0} · missed {1} · extra {2}\nTypically {3:F1} ms after the click (minus means early) · spread {4:F1} ms · {5:P0} of the beats were hit", "Geraakt {0} · gemist {1} · extra {2}\nGemiddeld {3:F1} ms na de tik (min betekent te vroeg) · spreiding {4:F1} ms · {5:P0} van de tellen geraakt", "Getroffen {0} · verpasst {1} · zusätzlich {2}\nTypisch {3:F1} ms nach dem Klick (Minus heißt zu früh) · Streuung {4:F1} ms · {5:P0} der Zählzeiten getroffen", "Touchés {0} · manqués {1} · en trop {2}\nEn général {3:F1} ms après le clic (moins = en avance) · dispersion {4:F1} ms · {5:P0} des temps joués", "Acertados {0} · omitidos {1} · extra {2}\nNormalmente {3:F1} ms después del clic (menos = antes) · dispersión {4:F1} ms · {5:P0} de los pulsos tocados");
        Add("TimingRequiresPlayback", "Press Start first, then start the check.", "Druk eerst op Starten en start dan de check.", "Drücken Sie zuerst Starten und starten Sie dann die Prüfung.", "Appuyez d’abord sur Démarrer, puis lancez le contrôle.", "Pulse primero Iniciar y luego inicie la comprobación.");
        Add("TimingPendingEdits", "Some edits are not playing yet. Press Stop, then Start, then start the check, so it follows what you hear.", "Sommige wijzigingen spelen nog niet. Druk op Stoppen en Starten en start dan de check, zodat die volgt wat u hoort.", "Einige Änderungen werden noch nicht gespielt. Drücken Sie Stoppen und Starten und starten Sie dann die Prüfung, damit sie dem folgt, was Sie hören.", "Certaines modifications ne sont pas encore jouées. Appuyez sur Arrêter puis Démarrer, puis lancez le contrôle pour qu’il suive ce que vous entendez.", "Algunos cambios aún no suenan. Pulse Detener y luego Iniciar, y después inicie la comprobación para que siga lo que oye.");
        Add("TimingTargetChanged", "The rhythm you picked is no longer in what is playing. Press Stop, then Start, and pick it again.", "Het gekozen ritme zit niet meer in wat wordt gespeeld. Druk op Stoppen en Starten en kies het opnieuw.", "Der gewählte Rhythmus ist nicht mehr in dem enthalten, was gespielt wird. Drücken Sie Stoppen und Starten und wählen Sie ihn erneut.", "Le rythme choisi ne fait plus partie de ce qui est joué. Appuyez sur Arrêter puis Démarrer et choisissez-le à nouveau.", "El ritmo elegido ya no está en lo que suena. Pulse Detener y Iniciar y elíjalo de nuevo.");
        Add("LibraryPartial", "Some library projects could not be read", "Sommige bibliotheekprojecten konden niet worden gelezen", "Einige Bibliotheksprojekte konnten nicht gelesen werden", "Certains projets de la bibliothèque sont illisibles", "No se pudieron leer algunos proyectos de la biblioteca");
        Add("LibraryLimited", "Library scan limit reached", "Scanlimiet van bibliotheek bereikt", "Scanlimit der Bibliothek erreicht", "Limite d’analyse de la bibliothèque atteinte", "Límite de lectura de la biblioteca alcanzado");
        Add("LibraryOverflow", "The library contains more than {0} project files. Only the first {0} files by path were checked; unreadable files count toward this limit. Other files remain unchanged and were not checked. Use Open project to load an unlisted file.", "De bibliotheek bevat meer dan {0} projectbestanden. Alleen de eerste {0} bestanden op pad zijn gecontroleerd; onleesbare bestanden tellen mee. Andere bestanden blijven ongewijzigd en zijn niet gecontroleerd. Gebruik Project openen voor een niet-getoond bestand.", "Die Bibliothek enthält mehr als {0} Projektdateien. Nur die ersten {0} Dateien nach Pfad wurden geprüft; unlesbare Dateien zählen mit. Weitere Dateien bleiben unverändert und ungeprüft. Nicht aufgeführte Dateien über Projekt öffnen laden.", "La bibliothèque contient plus de {0} fichiers projet. Seuls les {0} premiers, classés par chemin, ont été vérifiés ; les fichiers illisibles comptent dans cette limite. Les autres restent inchangés et non vérifiés. Utilisez Ouvrir un projet pour charger un fichier absent.", "La biblioteca contiene más de {0} archivos de proyecto. Solo se comprobaron los primeros {0} por ruta; los ilegibles cuentan para el límite. Los demás no se modificaron ni comprobaron. Use Abrir proyecto para cargar un archivo no mostrado.");
        Add("LibraryFailedPaths", "Valid projects remain available. {0} unreadable or invalid file(s):\n{1}", "Geldige projecten blijven beschikbaar. {0} onleesbare of ongeldige bestand(en):\n{1}", "Gültige Projekte bleiben verfügbar. {0} unlesbare oder ungültige Datei(en):\n{1}", "Les projets valides restent disponibles. {0} fichier(s) illisible(s) ou invalide(s) :\n{1}", "Los proyectos válidos siguen disponibles. {0} archivo(s) ilegible(s) o no válido(s):\n{1}");
