        Add("ExportBarsHelp", "Used when the project has no program of its own: this many bars are rendered. A project with a program is exported in full.", "Geldt als het project geen eigen programma heeft: zoveel maten worden gerenderd. Een project met programma wordt volledig geëxporteerd.", "Gilt, wenn das Projekt kein eigenes Programm hat: So viele Takte werden gerendert. Ein Projekt mit Programm wird vollständig exportiert.", "S’applique quand le projet n’a pas de programme : ce nombre de mesures est généré. Un projet avec programme est exporté en entier.", "Se usa cuando el proyecto no tiene programa propio: se generan tantos compases. Un proyecto con programa se exporta completo.");

        // Library page (docs/design/pages-design.md).
        Add("LibraryPurpose", "Open, save and export your projects, or start from a ready-made rhythm.", "Open, bewaar en exporteer uw projecten, of begin met een kant-en-klaar ritme.", "Projekte öffnen, speichern und exportieren – oder mit einem fertigen Rhythmus beginnen.", "Ouvrez, enregistrez et exportez vos projets, ou partez d’un rythme prêt à l’emploi.", "Abra, guarde y exporte sus proyectos, o empiece con un ritmo listo para usar.");
        Add("LibraryProjects", "My projects", "Mijn projecten", "Meine Projekte", "Mes projets", "Mis proyectos");
        Add("LibraryLoading", "Looking for projects…", "Projecten zoeken…", "Projekte werden gesucht …", "Recherche des projets…", "Buscando proyectos…");
        Add("LibraryUnreadable", "Your library could not be read. Check that its folder can be opened, then open this page again.", "Uw bibliotheek kon niet worden gelezen. Controleer of de map kan worden geopend en open deze pagina daarna opnieuw.", "Ihre Bibliothek konnte nicht gelesen werden. Prüfen Sie, ob sich der Ordner öffnen lässt, und öffnen Sie diese Seite dann erneut.", "Votre bibliothèque n’a pas pu être lue. Vérifiez que son dossier peut être ouvert, puis rouvrez cette page.", "No se pudo leer su biblioteca. Compruebe que se puede abrir su carpeta y vuelva a abrir esta página.");
        Add("LibraryNoMatch", "No project matches your search.", "Geen project komt overeen met uw zoekopdracht.", "Kein Projekt entspricht Ihrer Suche.", "Aucun projet ne correspond à votre recherche.", "Ningún proyecto coincide con su búsqueda.");
        Add("NotesProjectChanged", "The project was replaced before these notes were saved, so they were not added to the new one.", "Het project is vervangen voordat deze notities waren bewaard, dus ze zijn niet aan het nieuwe project toegevoegd.", "Das Projekt wurde ersetzt, bevor diese Notizen gespeichert waren; sie wurden dem neuen Projekt nicht hinzugefügt.", "Le projet a été remplacé avant l’enregistrement de ces notes ; elles n’ont pas été ajoutées au nouveau.", "El proyecto se sustituyó antes de guardar estas notas, así que no se añadieron al nuevo.");
        Add("CloseUnsaved", "Your last change is still being saved. Close the window again to leave anyway.", "Uw laatste wijziging wordt nog bewaard. Sluit het venster opnieuw om toch af te sluiten.", "Ihre letzte Änderung wird noch gespeichert. Schließen Sie das Fenster erneut, um trotzdem zu beenden.", "Votre dernière modification est encore en cours d’enregistrement. Fermez à nouveau la fenêtre pour quitter malgré tout.", "Su último cambio aún se está guardando. Cierre la ventana de nuevo para salir de todos modos.");
        Add("LibraryEmptyTitle", "No saved projects yet", "Nog geen opgeslagen projecten", "Noch keine gespeicherten Projekte", "Aucun projet enregistré", "Aún no hay proyectos guardados");
        Add("ExportTitle", "Export", "Exporteren", "Exportieren", "Exporter", "Exportar");
        Add("PresetsHelp", "Start from a ready-made rhythm. Your current project is saved to the library first.", "Begin met een kant-en-klaar ritme. Uw huidige project wordt eerst in de bibliotheek bewaard.", "Mit einem fertigen Rhythmus beginnen. Ihr aktuelles Projekt wird zuvor in der Bibliothek gespeichert.", "Partez d’un rythme prêt à l’emploi. Votre projet actuel est d’abord enregistré dans la bibliothèque.", "Empiece con un ritmo listo para usar. Su proyecto actual se guarda antes en la biblioteca.");
        Add("PresetDesc_open", "A plain 4/4 at 120 BPM with a one-bar count-in. A good place to start.", "Een gewone 4/4 op 120 BPM met een maat aftellen. Een goed beginpunt.", "Ein einfacher 4/4-Takt bei 120 BPM mit einem Takt Einzählen. Ein guter Anfang.", "Un simple 4/4 à 120 BPM avec une mesure de décompte. Un bon point de départ.", "Un 4/4 sencillo a 120 BPM con un compás de entrada. Un buen punto de partida.");
        Add("PresetDesc_compound-6-8", "6/8 felt in two: the dotted quarter note is 80 BPM and each of the two main beats splits into three.", "6/8 in twee gevoeld: de gepuncteerde kwartnoot is 80 BPM en elk van de twee hoofdtellen valt in drieën uiteen.", "6/8 in Zwei gefühlt: Die punktierte Viertelnote ist 80 BPM, jeder der zwei Hauptschläge teilt sich in drei.", "6/8 ressenti à deux temps : la noire pointée vaut 80 BPM et chacun des deux temps principaux se divise en trois.", "6/8 sentido en dos: la negra con puntillo es 80 BPM y cada uno de los dos pulsos principales se divide en tres.");
        Add("PresetDesc_additive-7-8", "Seven eighth notes grouped 2+2+3. The first note of each group is stressed.", "Zeven achtste noten gegroepeerd als 2+2+3. De eerste noot van elke groep krijgt nadruk.", "Sieben Achtelnoten, gruppiert als 2+2+3. Die erste Note jeder Gruppe wird betont.", "Sept croches groupées en 2+2+3. La première note de chaque groupe est accentuée.", "Siete corcheas agrupadas como 2+2+3. La primera nota de cada grupo se acentúa.");
        Add("PresetDesc_swing", "Eighth notes with a swing feel: long-short pairs instead of even ones.", "Achtste noten met swing: lang-kort-paren in plaats van gelijke.", "Achtelnoten mit Swing-Gefühl: lang-kurz-Paare statt gleichmäßiger.", "Croches avec un feeling swing : des paires longue-brève plutôt que régulières.", "Corcheas con sensación de swing: pares largo-corto en lugar de iguales.");
        Add("PresetDesc_polyrhythm-3-4", "Three evenly spaced clicks against four beats in the same bar.", "Drie gelijkmatig verdeelde tikken tegen vier tellen in dezelfde maat.", "Drei gleichmäßig verteilte Klicks gegen vier Schläge im selben Takt.", "Trois clics régulièrement espacés contre quatre temps dans la même mesure.", "Tres clics a distancias iguales contra cuatro pulsos en el mismo compás.");
        Add("PresetDesc_polymeter-3-4", "A pulse in three and a pulse in four, running side by side. They meet again every 12 beats.", "Een puls in drie en een puls in vier, naast elkaar. Ze komen elke 12 tellen weer samen.", "Ein Puls in Drei und ein Puls in Vier, nebeneinander. Sie treffen sich alle 12 Zählzeiten wieder.", "Une pulsation à trois et une à quatre, côte à côte. Elles se retrouvent tous les 12 temps.", "Un pulso en tres y otro en cuatro, en paralelo. Vuelven a coincidir cada 12 pulsos.");
        Add("PresetDesc_euclidean-5-8", "Five clicks spread as evenly as possible over eight steps.", "Vijf tikken zo gelijk mogelijk verdeeld over acht stappen.", "Fünf Klicks, so gleichmäßig wie möglich auf acht Schritte verteilt.", "Cinq clics répartis aussi régulièrement que possible sur huit pas.", "Cinco clics repartidos lo más uniformemente posible en ocho pasos.");
        Add("PresetDesc_paradiddle", "Sixteen strokes of right-hand and left-hand sticking to practise on a pad.", "Zestien slagen rechter- en linkerhandsticking om op een pad te oefenen.", "Sechzehn Schläge Rechts-Links-Handsatz zum Üben auf dem Pad.", "Seize coups de doigté main droite et gauche à travailler sur un pad.", "Dieciséis golpes de digitación derecha e izquierda para practicar en un pad.");
        Add("PresetDesc_warmup-ladder", "Starts at 80 BPM and speeds up by 4 BPM every eight bars, up to 112.", "Begint op 80 BPM en gaat elke acht maten 4 BPM sneller, tot 112.", "Beginnt bei 80 BPM und wird alle acht Takte um 4 BPM schneller, bis 112.", "Commence à 80 BPM et accélère de 4 BPM toutes les huit mesures, jusqu’à 112.", "Empieza a 80 BPM y acelera 4 BPM cada ocho compases, hasta 112.");
        Add("PresetDesc_internal-time", "Two bars you hear, then two bars of silence, over and over. Keep the beat going yourself through the gaps.", "Twee maten hoorbaar, dan twee maten stilte, steeds opnieuw. Houd zelf de maat vast tijdens de stiltes.", "Zwei Takte hörbar, dann zwei Takte Stille, immer wieder. Halten Sie den Takt in den Lücken selbst.", "Deux mesures audibles, puis deux mesures de silence, en boucle. Gardez vous-même le tempo pendant les silences.", "Dos compases audibles y luego dos de silencio, una y otra vez. Mantenga usted mismo el pulso durante los silencios.");
        Add("PresetDesc_ramp-domains", "Speeds up from 60 to 120 BPM, slows back down to 60, then settles at 80. Two different ways of changing tempo, side by side.", "Versnelt van 60 naar 120 BPM, vertraagt terug naar 60 en komt dan uit op 80. Twee manieren om het tempo te veranderen, naast elkaar.", "Beschleunigt von 60 auf 120 BPM, wird wieder auf 60 langsamer und pendelt sich bei 80 ein. Zwei Arten der Tempoänderung im Vergleich.", "Accélère de 60 à 120 BPM, ralentit jusqu’à 60, puis se stabilise à 80. Deux façons de changer de tempo, côte à côte.", "Acelera de 60 a 120 BPM, vuelve a 60 y se asienta en 80. Dos formas de cambiar el tempo, una junto a otra.");
        Add("PresetDesc_seeded-density", "About half of the clicks are left out at random, so you have to keep the pulse yourself. The same pattern plays every time.", "Ongeveer de helft van de tikken valt willekeurig weg, dus u moet zelf de puls vasthouden. Elke keer klinkt hetzelfde patroon.", "Etwa die Hälfte der Klicks entfällt zufällig, Sie müssen den Puls also selbst halten. Jedes Mal erklingt dasselbe Muster.", "Environ la moitié des clics sont omis au hasard : à vous de garder la pulsation. Le même motif revient à chaque fois.", "Aproximadamente la mitad de los clics se omiten al azar, así que debe mantener usted el pulso. Suena el mismo patrón cada vez.");

        // Stage page (docs/design/pages-design.md).
        Add("StagePurpose", "A big, steady view for performing, with a setlist to move from song to song.", "Een grote, rustige weergave voor optreden, met een setlijst om van song naar song te gaan.", "Eine große, ruhige Ansicht für den Auftritt, mit einer Setliste von Song zu Song.", "Un affichage grand et stable pour jouer, avec une liste de scène pour passer d’un morceau à l’autre.", "Una vista grande y estable para actuar, con un repertorio para pasar de canción en canción.");
        Add("NowPlaying", "Now playing", "Nu aan het spelen", "Läuft gerade", "En cours", "Sonando ahora");
        Add("UpNextBadge", "Up next", "Hierna", "Als Nächstes", "Ensuite", "A continuación");
        Add("NothingUpNext", "Nothing selected: choose a song in the setlist.", "Niets geselecteerd: kies een song in de setlijst.", "Nichts ausgewählt: Wählen Sie einen Song in der Setliste.", "Rien de sélectionné : choisissez un morceau dans la liste.", "Nada seleccionado: elija una canción del repertorio.");
        Add("SetlistHelp", "The song you select plays next.", "De song die u selecteert, komt hierna.", "Der ausgewählte Song kommt als Nächstes.", "Le morceau sélectionné passe ensuite.", "La canción seleccionada suena a continuación.");
        Add("SetlistEmptyTitle", "No songs yet", "Nog geen songs", "Noch keine Songs", "Aucun morceau", "Aún no hay canciones");
        Add("NotesFor", "Notes for “{0}”", "Notities voor “{0}”", "Notizen zu „{0}“", "Notes pour « {0} »", "Notas de «{0}»");
        Add("NotesSaved", "Saved when you leave this box.", "Wordt bewaard zodra u het vak verlaat.", "Wird gespeichert, sobald Sie das Feld verlassen.", "Enregistré quand vous quittez ce champ.", "Se guarda al salir de este cuadro.");
        Add("LockHelp", "Stops accidental changes to the project while you perform. Playback is not affected.", "Voorkomt per ongeluk wijzigen van het project tijdens het optreden. Afspelen blijft werken.", "Verhindert versehentliche Änderungen am Projekt während des Auftritts. Die Wiedergabe bleibt möglich.", "Évite les modifications accidentelles du projet pendant la prestation. La lecture n’est pas affectée.", "Evita cambios accidentales en el proyecto durante la actuación. La reproducción no se ve afectada.");

        // Train page (docs/design/pages-design.md).
        Add("TrainPurpose", "Follow a practice program, and check how closely your key presses land on the clicks.", "Volg een oefenprogramma en controleer hoe dicht uw toetsdrukken bij de tikken liggen.", "Folgen Sie einem Übungsprogramm und prüfen Sie, wie genau Ihre Tastendrücke die Klicks treffen.", "Suivez un programme d’entraînement et vérifiez la précision de vos pressions sur les clics.", "Siga un programa de práctica y compruebe cuánto se acercan sus pulsaciones a los clics.");
        Add("TrainProgramTitle", "Practice program", "Oefenprogramma", "Übungsprogramm", "Programme d’entraînement", "Programa de práctica");
        Add("TrainProgramHelp", "A program changes tempo and time signature step by step, for example to build up speed.", "Een programma verandert stap voor stap het tempo en de maatsoort, bijvoorbeeld om snelheid op te bouwen.", "Ein Programm ändert Tempo und Taktart Schritt für Schritt, zum Beispiel um Geschwindigkeit aufzubauen.", "Un programme modifie pas à pas le tempo et la mesure, par exemple pour gagner en vitesse.", "Un programa cambia el tempo y el compás paso a paso, por ejemplo para ganar velocidad.");
        Add("EditInStudio", "Edit in Studio", "Bewerken in Studio", "Im Studio bearbeiten", "Modifier dans Studio", "Editar en Estudio");
        Add("ProgramEmptyTitle", "No program yet", "Nog geen programma", "Noch kein Programm", "Aucun programme", "Aún no hay programa");
        Add("BuildProgram", "Build a program in Studio", "Programma bouwen in Studio", "Programm im Studio erstellen", "Créer un programme dans Studio", "Crear un programa en Estudio");
        Add("ProgramIdle", "Not playing. Press Start to hear the program from the beginning.", "Speelt niet. Druk op Starten om het programma vanaf het begin te horen.", "Wird nicht gespielt. Starten drücken, um das Programm von Anfang an zu hören.", "À l’arrêt. Appuyez sur Démarrer pour entendre le programme depuis le début.", "Detenido. Pulse Iniciar para oír el programa desde el principio.");
        Add("TrainProgramChanged", "Status, chart and progress follow what is playing. The steps below are the program as you changed it in Studio; they are heard from the next Start.", "Status, grafiek en voortgang volgen wat nu speelt. De stappen hieronder zijn het programma zoals u het in Studio hebt gewijzigd; ze klinken vanaf de volgende Start.", "Status, Diagramm und Fortschritt folgen dem, was gerade spielt. Die Schritte unten sind das Programm, wie Sie es im Studio geändert haben; sie sind ab dem nächsten Start zu hören.", "L’état, le graphique et la progression suivent ce qui joue. Les étapes ci-dessous sont le programme tel que vous l’avez modifié dans Studio ; elles s’entendent au prochain démarrage.", "El estado, el gráfico y el progreso siguen lo que suena. Los pasos de abajo son el programa como lo cambió en Estudio; se oyen desde el próximo inicio.");
        Add("TrainProgramRemoved", "You removed this program in Studio. It keeps playing until you press Stop; after that the rhythm simply repeats.", "U hebt dit programma in Studio verwijderd. Het blijft spelen tot u op Stoppen drukt; daarna herhaalt het ritme zich gewoon.", "Sie haben dieses Programm im Studio entfernt. Es spielt weiter, bis Sie Stoppen drücken; danach wiederholt sich der Rhythmus einfach.", "Vous avez supprimé ce programme dans Studio. Il continue de jouer jusqu’à ce que vous appuyiez sur Arrêter ; ensuite, le rythme se répète simplement.", "Eliminó este programa en Estudio. Sigue sonando hasta que pulse Detener; después el ritmo simplemente se repite.");
        Add("UnitMs", "ms", "ms", "ms", "ms", "ms");
        Add("IncludeSilentHelp", "Beats the metronome stays silent on (gaps, muted layers, chance) still count, so you practise keeping time yourself.", "Tellen waarop de metronoom stil blijft (stiltes, gedempte lagen, kans) tellen toch mee, zodat u zelf de tijd leert houden.", "Zählzeiten, auf denen das Metronom schweigt (Lücken, stumme Ebenen, Zufall), zählen trotzdem, damit Sie selbst den Takt halten üben.", "Les temps où le métronome reste muet (silences, couches coupées, hasard) comptent quand même : vous travaillez la tenue du tempo.", "Los pulsos en los que el metrónomo calla (silencios, capas silenciadas, azar) también cuentan, para que practique mantener el tiempo usted mismo.");
    }
